'use strict';
let DATA, items=[], period='1D', compareMode='prices', compareRange='1M', selected=['spx','gold'], detailId=null, detailRange='1M';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,n=2)=>new Intl.NumberFormat('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}).format(v);
const sign=(v,n=2)=>(v>=0?'+':'−')+fmt(Math.abs(v),n);
const day=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'});
const hkt=t=>new Date(typeof t==='number'?t*1000:t).toLocaleString('en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'Asia/Hong_Kong'})+' HKT';
const link=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const dateNum=d=>Date.parse(d+'T12:00:00Z');
const byId=id=>items.find(i=>i.id===id);
function cutoff(end,range){const d=new Date(dateNum(end)); if(range==='1W')d.setUTCDate(d.getUTCDate()-7);if(range==='1M')d.setUTCMonth(d.getUTCMonth()-1);if(range==='3M')d.setUTCMonth(d.getUTCMonth()-3);if(range==='1Y')d.setUTCFullYear(d.getUTCFullYear()-1);return d.toISOString().slice(0,10);}
function sliced(i,range){const start=cutoff(i.series.at(-1).date,range);return i.series.filter(p=>p.date>=start);}
function movement(i,p=period){const m=i.performance[p];if(!m)return '<span>Not enough verified history</span>'; const bond=i.group==='Bonds',v=bond?m.bp:m.pct;return `<strong class="${bond?'yield-move':v>=0?'positive':'negative'}">${sign(v,bond?1:2)}${bond?' bp':'%'}</strong><span class="movement-period">${esc(p)} ${bond?'yield change':'price change'}</span>`;}
function exact(i,p=period){const m=i.performance[p];if(!m)return '';return `${m.baseTime?hkt(m.baseTime):day(m.baseDate)+' daily close'} → ${hkt(m.endTime)}`;}
function trend(i){const w=i.performance['1W'],m=i.performance['1M'],bond=i.group==='Bonds';return bond?`Yield ${sign(w.bp,1)} bp over 1W; ${sign(m.bp,1)} bp over 1M. ${m.bp>0?'Borrowing benchmark is higher over the month.':'Borrowing benchmark is lower over the month.'}`:`${sign(w.pct)}% over 1W and ${sign(m.pct)}% over 1M${i.id==='jpy'?'; a rise means a weaker yen.':'.'}`;}
function segments(values,active,attr){return `<div class="segments" aria-label="${attr==='data-period'?'Performance period':'Chart range'}">${values.map(v=>`<button type="button" ${attr}="${v}" aria-pressed="${active===v}" class="${active===v?'active':''}">${v}</button>`).join('')}</div>`;}
function renderTop(){
 const latest=items.map(i=>i.sessionDate).sort().at(-1), bonds=items.filter(i=>i.group==='Bonds'), stocks=items.filter(i=>i.group==='Stocks'), crypto=items.filter(i=>i.group==='Crypto');
 const big=[...items].sort((a,b)=>Math.abs((b.group==='Bonds'?b.performance['1D'].bp:b.performance['1D'].pct)||0)-Math.abs((a.group==='Bonds'?a.performance['1D'].bp:a.performance['1D'].pct)||0))[0];
 $('#edition').innerHTML=`<strong>As of ${hkt(DATA.asOf)}</strong><br><span>Latest available observations · session dates vary by market</span>`;
 $('.stories').innerHTML=`<article><span class="number">01 / BONDS</span><h3>Yields moved higher</h3><p>${bonds.map(i=>`${i.name.replace('US ','')} ${sign(i.performance['1D'].bp,1)} bp`).join('; ')} versus the previous available close. Yield changes are not bond returns.</p>${link(bonds[0].historyUrl,'Check bond-yield history')}</article><article><span class="number">02 / STOCKS</span><h3>Equity moves differed</h3><p>${stocks.map(i=>`${i.name} ${sign(i.performance['1D'].pct)}%`).join('; ')}. Different session dates and index composition limit direct comparison.</p>${link(stocks[0].historyUrl,'Check index history')}</article><article><span class="number">03 / LARGEST MOVE</span><h3>${esc(big.name)}</h3><p>${big.group==='Bonds'?`${sign(big.performance['1D'].bp,1)} bp yield move`:`${sign(big.performance['1D'].pct)}% price move`} from its previous available close. The price series verifies the move, not a single cause.</p>${link(big.historyUrl,'Check source history')}</article>`;
 $('.why').innerHTML=`<strong>Why this matters</strong><p><b>Learning interpretation:</b> ${crypto.map(i=>i.name+' '+sign(i.performance['1D'].pct)+'%').join(' and ')} while Treasury yields rose. That combination can be consistent with tighter financial conditions, but one session is evidence of co-movement rather than proof of causation.</p>`;
 $('#performance').innerHTML=segments(['1D','1W','1M','YTD'],period,'data-period');
 $('#period-note').innerHTML=`Refreshed ${hkt(DATA.asOf)} · Not streaming · Quote times and session dates vary · Hover dotted terms for English / 中文.`;
 $('#methodology').innerHTML=`<details><summary>Sources, timing & calculation notes</summary><div class="method-grid"><div><h3>Latest verified pull</h3><p>Prices and daily histories were fetched from Yahoo Finance’s chart feed on ${hkt(DATA.asOf)}. This is a dated refresh, not a streaming feed. ${link('refresh-audit.json','View refresh audit')} Quote times can precede retrieval.</p><p>The newest session in this set is ${day(latest)}. Each card shows its own provider update time because Asian, European, US and 24/7 markets do not share one close.</p></div><div><h3>Comparable, not identical</h3><p>1D, 1W and 1M use the latest available observation on or before the calendar lookback date; YTD uses the last available 2025 close. Percent change = (latest / reference − 1) × 100. Bond yield changes are shown in basis points.</p><p>Comparison charts use only common dates and do not fill missing sessions. Prices are rebased to 100; yields remain separate. FX direction follows the displayed pair.</p></div><div><h3>Reading the update</h3><p>Card explanations describe verified movements without assigning an unverified catalyst. Related-news links in expanded cards are dated background reading and display their publication date.</p><p>Futures histories can roll between contracts. Correlation is not proof of causation.</p><p>${link('https://www.cnbc.com/markets/','CNBC Markets')} · ${link('https://finance.caixin.com/h5/finance','Caixin Finance')} · ${link('https://www.ftchinese.com/','FTChinese')}</p></div></div></details><p>Morning Meetings · Caylin / CUHK MBA / FINA6010E · Five markets, one learning routine.</p>`;
 document.querySelectorAll('.notice.edition-age').forEach(n=>n.remove());
 const age=(Date.now()-Date.parse(DATA.asOf))/86400000;if(false){const banner=document.createElement('p');banner.className='notice edition-age';banner.textContent='Archived edition: these figures were verified on '+hkt(DATA.asOf)+'. They are not current quotes.';$('.titlebar').after(banner);}
}
function renderCards(){
 const groups=['Stocks','Foreign Exchange','Commodities','Bonds','Crypto'];
 $('#cards').innerHTML=groups.map((g,n)=>`<section class="asset-section" data-market="${n}" aria-labelledby="group-${n}"><div class="asset-heading"><span class="asset-number">0${n+1}</span><h2 id="group-${n}">${g}</h2></div><div class="card-grid">${items.filter(i=>i.group===g).map(i=>{const bond=i.group==='Bonds',w=i.performance['1W'],m=i.performance['1M'];return `<article class="card" id="card-${i.id}"><div class="cardtop"><span class="ticker">${esc(i.symbol)}</span><span class="status">${i.group==='Crypto'?'24/7 SNAPSHOT':'LATEST'}</span></div><h3>${i.name}</h3><div class="price">${fmt(i.quote,i.digits)} <small>${i.unit}</small></div><div class="movement" title="${esc(exact(i))}">${movement(i)}</div><div class="mini-chart"><div class="mini-caption"><span>1M ${bond?'yield':'price'} trend</span><span>${bond?'Yield %':'Daily'}</span></div><div class="spark" id="spark-${i.id}"></div></div><div class="quick-trend" aria-label="Observed trend"><span>1W <b>${bond?sign(w.bp,1)+' bp':sign(w.pct)+'%'}</b></span><span>1M <b>${bond?sign(m.bp,1)+' bp':sign(m.pct)+'%'}</b></span></div><div class="insight-copy"><span class="eyebrow">Market insight</span><p class="explanation" title="${esc(i.why)}">${i.why}</p></div>${(i.id==='silver'||i.dataFlag)?'<div class="card-notice"><span class="data-flag">Quote / close differ · see details</span></div>':''}<div class="overview-foot"><span>${link(i.quoteUrl,'Quote')} · ${link(i.newsUrl,'Story')}</span><button class="textbutton" data-detail="${i.id}" aria-label="Open ${i.name} details and chart">Details ↗</button></div></article>`;}).join('')}</div></section>`).join('');
 for(const i of items)drawChart($('#spark-'+i.id),[{item:i,points:sliced(i,'1M')}],{mini:true});
}
function drawChart(container,series,options={}){
 const mini=!!options.mini, W=mini?500:900,H=mini?104:340,L=mini?4:70,R=mini?4:20,T=mini?12:25,B=mini?10:40;
 const all=series.flatMap(s=>s.points),dates=[...new Set(all.map(p=>p.date))].sort();
 if(dates.length<2){container.innerHTML='<p class="subtle">Not enough verified observations for this range.</p>';return;}
 const values=all.map(p=>p.y??p.v),min=Math.min(...values),max=Math.max(...values),pad=(max-min)*.14||1,lo=min-pad,hi=max+pad;
 const x=d=>L+(dateNum(d)-dateNum(dates[0]))/(dateNum(dates.at(-1))-dateNum(dates[0]))*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);
 const colors=options.compare?['#225dcc','#b65c05','#8350bb']:[series[0].item.group==='Bonds'?'#526bc6':values.at(-1)>=values[0]?'#07816a':'#b83f5c'];
 let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(series.map(s=>s.item.name).join(', '))} historical chart${options.rebase?', rebased to 100':''}" preserveAspectRatio="none">`;
 if(!mini){for(let k=0;k<4;k++){let v=lo+(hi-lo)*k/3;svg+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e1e7ef"/><text x="${L-10}" y="${y(v)+4}" text-anchor="end">${fmt(v,options.rebase||options.bp?1:series[0].item.group==='Bonds'?2:series[0].item.digits===4?4:values[0]>1000?0:2)}</text>`;}svg+=`<text x="${L}" y="${H-8}">${esc(day(dates[0]))}</text><text x="${W-R}" y="${H-8}" text-anchor="end">${esc(day(dates.at(-1)))}</text>`;}
 if(options.rebase&&100>=lo&&100<=hi)svg+=`<line x1="${L}" x2="${W-R}" y1="${y(100)}" y2="${y(100)}" stroke="#9aabc0" stroke-dasharray="5 5"/>`;
 series.forEach((s,idx)=>{const path=s.points.map((p,k)=>`${k?'L':'M'}${x(p.date).toFixed(2)},${y(p.y??p.v).toFixed(2)}`).join(' ');svg+=`<path d="${path}" fill="none" stroke="${colors[idx]}" stroke-width="${mini?2:2.5}" stroke-linecap="round" stroke-linejoin="round"/>`; const end=s.points.at(-1);svg+=`<circle cx="${x(end.date)}" cy="${y(end.y??end.v)}" r="3" fill="${colors[idx]}"/>`;});
 const event=DATA.events[0];if(options.event&&event.date>=dates[0]&&event.date<=dates.at(-1))svg+=`<line x1="${x(event.date)}" x2="${x(event.date)}" y1="${T}" y2="${H-B}" stroke="#8a9db4" stroke-dasharray="3 4"/><text x="${Math.min(x(event.date)+7,W-125)}" y="16">16 Sep · Fed +25 bp</text>`;
 svg+=`<line class="cursor-line" x1="${L}" x2="${L}" y1="${T}" y2="${H-B}" stroke="#63758b" opacity="0" stroke-dasharray="2 3"/></svg>`;
 container.classList.add('chart');container.innerHTML=svg+'<div class="chart-tip" role="status" hidden></div>';
 container.tabIndex=0;container.setAttribute('aria-label','Historical chart. Use left and right arrows to read observations.');
 const tip=container.querySelector('.chart-tip'),cursor=container.querySelector('.cursor-line');let index=dates.length-1;
 function show(k){index=Math.max(0,Math.min(k,dates.length-1));const d=dates[index];tip.innerHTML=`<b>${day(d)}</b>`+series.map((s,j)=>{const p=s.points.find(p=>p.date===d);if(!p)return '';return `<div><span style="color:${colors[j]}">●</span> ${s.item.name}: <strong>${options.rebase?fmt(p.y,2)+' indexed · ':options.bp?sign(p.y,1)+' bp · ':''}${fmt(p.v,s.item.digits)} ${s.item.unit}</strong><small>${p.kind==='Latest provider snapshot'?hkt(p.sourceTimestamp):esc(p.kind)+' · '+(s.item.group==='Crypto'?'UTC day':'session date')}</small></div>`;}).join('');tip.hidden=false;cursor.setAttribute('x1',x(d));cursor.setAttribute('x2',x(d));cursor.setAttribute('opacity','1');}
 container.addEventListener('pointermove',e=>{const rect=container.getBoundingClientRect(),px=(e.clientX-rect.left)/rect.width*W;let best=0;dates.forEach((d,k)=>{if(Math.abs(x(d)-px)<Math.abs(x(dates[best])-px))best=k;});show(best);});
 container.addEventListener('pointerleave',()=>{tip.hidden=true;cursor.setAttribute('opacity','0');});container.addEventListener('focus',()=>show(index));container.addEventListener('blur',()=>{tip.hidden=true;cursor.setAttribute('opacity','0');});
 container.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();show(e.key==='Home'?0:e.key==='End'?dates.length-1:index+(e.key==='ArrowLeft'?-1:1));}});
}
function relatedNewsMarkup(i){return `<section class="related-news" aria-labelledby="related-news-title"><div class="sectionline"><div><p class="eyebrow">READ THE CONTEXT</p><h3 id="related-news-title">Related news</h3></div><span class="subtle">For the 19 Sep 2026 edition</span></div><div class="news-grid">${i.relatedNews.map(n=>`<article class="news-card"><div class="news-meta"><span>${esc(n.source)}</span><time datetime="${n.date}">${day(n.date)}</time></div><h4>${link(n.url,esc(n.title))}</h4><span class="news-type">${esc(n.type)}</span></article>`).join('')}</div><p class="news-caption">Links open the source article. Headlines above are concise topic summaries; these are dated readings, not a live news feed.</p></section>`;}
function renderDetail(){const i=byId(detailId);if(!i)return;const points=sliced(i,detailRange);$('#detail').dataset.market=String(['Stocks','Foreign Exchange','Commodities','Bonds','Crypto'].indexOf(i.group));
 $('#detail-content').innerHTML=`<div class="sectionline"><div><p class="eyebrow">${i.group} · ${i.symbol}</p><h2 id="detail-title">${i.name}</h2></div><button class="close-button" data-close aria-label="Close chart">✕</button></div><div class="detail-head"><div><div class="price">${fmt(i.quote,i.digits)} <small>${i.unit}</small></div><div class="movement">${movement(i)}</div></div>${segments(['1W','1M','3M','1Y'],detailRange,'data-detail-range')}</div><p class="subtle">${exact(i)} · Performance selection is independent of the chart range.</p><div id="large-chart"></div><p class="subtle">Chart: ${day(points[0].date)} → ${day(points.at(-1).date)} · ${points.length} observations · ${i.unit}. Hover, tap, or use arrow keys for values.</p><div class="detail-context"><h3>Market insight</h3><p class="instrument-sub">${i.subtitle} · Provider update: ${hkt(i.quoteTime)}</p><p>${i.why}</p><p class="context-type">${i.whyType} · ${link(i.newsUrl,i.newsName)}</p><p class="trend"><b>Observed trend</b>${trend(i)}</p>${insightMarkup(i)}${leadersMarkup(i)}<div class="term"><b>${i.term}</b><p>${i.definition}</p>${link(i.termUrl,'Learn the term')}</div></div>${yfinanceMarkup(i)}${relatedNewsMarkup(i)}<p class="quality-note">${i.note}</p>${points[0].date<='2026-09-16'&&points.at(-1).date>='2026-09-16'?`<p class="event-note">Verified event: ${link(DATA.events[0].url,'Fed +25 bp on 16 Sep, 14:00 EDT / 17 Sep, 02:00 HKT')}. The marker locates the announcement; it does not prove causation.</p>`:''}<p>${link(i.newsUrl,i.newsName)} · ${link(i.historyUrl,'Yahoo Finance history')} · ${link(i.rawUrl,'Source observations')}</p><details><summary>View chart data & exact performance references</summary><div class="table-wrap"><table><thead><tr><th>Performance</th><th>Reference</th><th>Reference value</th><th>Move</th></tr></thead><tbody>${Object.entries(i.performance).map(([p,m])=>`<tr><td>${p}</td><td>${m.baseTime?hkt(m.baseTime):day(m.baseDate)+' close'}</td><td>${fmt(m.base,i.digits)} ${i.unit}</td><td>${i.group==='Bonds'?sign(m.bp,1)+' bp; '+sign(m.pct)+'% relative yield change (not return)':sign(m.pct)+'%'}</td></tr>`).join('')}</tbody></table><table><thead><tr><th>Date / session</th><th>Value · ${i.unit}</th><th>Observation</th></tr></thead><tbody>${points.map(p=>`<tr><td>${day(p.date)}</td><td>${fmt(p.v,i.digits)}</td><td>${p.kind}${p.kind==='Latest provider snapshot'?' · '+hkt(p.sourceTimestamp):''}</td></tr>`).join('')}</tbody></table></div></details>`;
 drawChart($('#large-chart'),[{item:i,points}],{event:true});$('#detail').setAttribute('aria-labelledby','detail-title');}
function openDetail(id){if(!byId(id))throw Error('Unknown instrument');detailId=id;detailRange='1M';renderDetail();if(!$('#detail').open)$('#detail').showModal();}
function commonSeries(list,range){if(!list.length)return [];const end=list.map(i=>i.series.at(-1).date).sort()[0],start=cutoff(end,range);const dates=list[0].series.map(p=>p.date).filter(d=>d>=start&&d<=end&&list.every(i=>i.series.some(p=>p.date===d)));return list.map(i=>({item:i,points:dates.map(d=>i.series.find(p=>p.date===d))}));}
function renderComparison(){const bonds=compareMode!=='prices';const allowed=items.filter(i=>(i.group==='Bonds')===bonds);const list=selected.map(byId);const series=commonSeries(list,compareRange);for(const s of series){const base=s.points[0]?.v;s.points=s.points.map(p=>({...p,y:compareMode==='prices'?p.v/base*100:compareMode==='bp'?(p.v-base)*100:p.v}));}
 $('#comparison').className='panel comparison';$('#comparison').innerHTML=`<div class="sectionline"><div><p class="eyebrow">OPTIONAL DEEPER EXPLORATION</p><h2>Put the moves in perspective</h2></div>${segments(['1W','1M','3M','1Y'],compareRange,'data-compare-range')}</div><div class="compare-tools"><label>Compare <select id="compare-mode"><option value="prices" ${compareMode==='prices'?'selected':''}>Prices · rebased to 100</option><option value="yields" ${compareMode==='yields'?'selected':''}>Bonds · yield levels (%)</option><option value="bp" ${compareMode==='bp'?'selected':''}>Bonds · change in basis points</option></select></label><p class="subtle">Choose up to three instruments. Bond yields have their own view.</p></div><div class="checks">${allowed.map(i=>`<label><input type="checkbox" value="${i.id}" ${selected.includes(i.id)?'checked':''} ${!selected.includes(i.id)&&selected.length>=3?'disabled':''}>${i.name}</label>`).join('')}</div><p id="selection-message" aria-live="polite" class="subtle">${selected.length} selected</p><div id="compare-chart"></div><div class="legend">${series.map((s,j)=>`<span><i style="background:${['#225dcc','#b65c05','#8350bb'][j]}"></i>${s.item.name}</span>`).join('')}</div><p class="subtle">${series[0]?.points.length?`${day(series[0].points[0].date)} → ${day(series[0].points.at(-1).date)} · ${series[0].points.length} common session dates. `:''}${bonds?'Yield changes are not bond investment returns.'+(activeSet==='alternate'?' The 13-week bill uses discount yield; the 5-year note uses yield to maturity. Levels have different calculation bases.':''):'100 = each instrument’s value on the first common date; 105 means a 5% rise in its quoted price.'} Different market close times remain; there is no currency conversion or dividend adjustment. Futures can include contract rolls.</p>`;
 if(series.length)drawChart($('#compare-chart'),series,{compare:true,rebase:!bonds,bp:compareMode==='bp'});else $('#compare-chart').innerHTML='<p class="empty">Select an instrument to begin your comparison.</p>';
}
function setPerformance(p){if(!['1D','1W','1M','YTD'].includes(p))throw Error('Invalid performance period');period=p;document.querySelectorAll('[data-period]').forEach(b=>{b.classList.toggle('active',b.dataset.period===p);b.setAttribute('aria-pressed',String(b.dataset.period===p));});renderCards();if($('#detail').open)renderDetail();}
function setComparison(ids,mode,range){if(!['prices','yields','bp'].includes(mode)||!['1W','1M','3M','1Y'].includes(range)||!Array.isArray(ids)||ids.length>3||new Set(ids).size!==ids.length||ids.some(id=>!byId(id)||(byId(id).group==='Bonds')!==(mode!=='prices')))throw Error('Select up to three distinct valid instruments; bond yields must stay separate.');selected=ids;compareMode=mode;compareRange=range;renderComparison();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)setView(b.dataset.view);if(b.dataset.set)switchSet(b.dataset.set);if(b.id==='refresh-examples'){if(savedSets.alternate)switchSet(activeSet==='original'?'alternate':'original');else loadAlternate();}if(b.dataset.period)setPerformance(b.dataset.period);if(b.dataset.detail)openDetail(b.dataset.detail);if(b.hasAttribute('data-close'))$('#detail').close();if(b.dataset.detailRange){detailRange=b.dataset.detailRange;renderDetail();}if(b.dataset.compareRange){compareRange=b.dataset.compareRange;renderComparison();}});
document.addEventListener('change',e=>{if(e.target.id==='compare-mode')setComparison(defaultComparison(e.target.value),e.target.value,compareRange);if(e.target.matches('.checks input')){const id=e.target.value;setComparison(e.target.checked?[...selected,id]:selected.filter(x=>x!==id),compareMode,compareRange);}});
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();const tools=[{name:'configure_market_comparison',description:'Configure the visible comparison for up to three instruments. Use prices for rebased price series or yields/bp for bonds only.',inputSchema:{type:'object',properties:{instruments:{type:'array',items:{type:'string'},maxItems:3,uniqueItems:true},mode:{type:'string',enum:['prices','yields','bp']},range:{type:'string',enum:['1W','1M','3M','1Y']}},required:['instruments','mode','range'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){setComparison(input.instruments,input.mode,input.range);return {selected,mode:compareMode,range:compareRange};}},{name:'read_market_snapshot',description:'Read the verified static edition and current dashboard selections. Does not fetch live prices.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {exampleSet:activeSet,asOf:DATA.asOf,performancePeriod:period,comparison:{selected,mode:compareMode,range:compareRange},instruments:items.map(i=>({id:i.id,name:i.name,value:i.quote,unit:i.unit,quoteTime:hkt(i.quoteTime)}))};}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
const savedSets={}, setPreferences={}; let activeSet='original',loadingSet=false, dashboardView='overview';
function setView(view){if(!['overview','comparison','brief'].includes(view))return;dashboardView=view;document.body.dataset.view=view;renderSetControls();if(view==='comparison')renderComparison();}

function defaultComparison(mode){return mode==='prices'?[items.find(i=>i.group==='Stocks').id,items.find(i=>i.group==='Commodities').id]:items.filter(i=>i.group==='Bonds').map(i=>i.id);}
function validateSet(d,other){const groups=['Stocks','Foreign Exchange','Commodities','Bonds','Crypto'];if(!d||!Array.isArray(d.instruments)||d.instruments.length!==10||new Set(d.instruments.map(i=>i.id)).size!==10||groups.some(g=>d.instruments.filter(i=>i.group===g).length!==2)||d.instruments.some(i=>!Number.isFinite(i.quote)||!i.series?.length||!i.relatedNews?.length||other?.instruments.some(x=>x.id===i.id||x.symbol===i.symbol)))throw Error('Invalid example set');return d;}
function renderSetControls(message=''){$('#set-controls').innerHTML=`<div class="set-actions"><div class="segments" aria-label="Saved example set">${[['original','Set 1 · Original'],['alternate','Set 2 · Different examples']].map(([id,label])=>`<button data-set="${id}" aria-pressed="${id===activeSet}" class="${id===activeSet?'active':''}" ${!savedSets[id]||loadingSet?'disabled':''}>${label}</button>`).join('')}</div>${!savedSets.alternate?`<button id="refresh-examples" class="refresh-button" ${loadingSet||!savedSets.original?'disabled':''}>${loadingSet?'Loading verified examples…':'↻ Refresh examples'}</button>`:'<button id="refresh-examples" class="refresh-button" title="Switch to the other saved example set; does not fetch live prices">↻ Refresh examples</button>'}<button data-view="${dashboardView==='comparison'?'overview':'comparison'}" class="refresh-button compare-button">${dashboardView==='comparison'?'← Market Overview':'Compare Markets'}</button><button data-view="${dashboardView==='brief'?'overview':'brief'}" class="textbutton">${dashboardView==='brief'?'← Market Overview':'Market Brief'}</button></div><p class="set-status" role="status">${esc(message||(savedSets.alternate?'Two saved sets · 20 instruments':'Refresh examples loads a second saved set of 10 instruments'))}</p>`;}
function switchSet(id){if(!savedSets[id]||loadingSet)return;if(DATA)setPreferences[activeSet]={period,compareMode,compareRange,selected:[...selected]};activeSet=id;DATA=savedSets[id];items=DATA.instruments;const pref=setPreferences[id];period=pref?.period||'1D';compareMode=pref?.compareMode||'prices';compareRange=pref?.compareRange||'1M';selected=pref?[...pref.selected]:defaultComparison('prices');detailId=null;if($('#detail').open)$('#detail').close();renderTop();if(id==='alternate')renderAlternateBrief();renderCards();renderComparison();renderSetControls();}
function renderAlternateBrief(){const stories=[['01 / STOCKS','Two indices, different directions',`Nasdaq ${sign(byId('nasdaq').performance['1D'].pct)}%; Dow ${sign(byId('dow').performance['1D'].pct)}% versus their previous daily closes. Index composition helps explain why “the market” has more than one result.`,'nasdaq'],['02 / FOREIGN EXCHANGE','Local data still matters','GBP and AUD moved in the latest observations versus the US dollar. Read the displayed percentage changes for direction; the price series alone does not prove the catalyst.','aud'],['03 / BONDS','A yield is not a return',`The 5-year yield moved ${sign(byId('ust5').performance['1D'].bp,1)} bp. The 13-week bill uses a different discount-yield convention; compare their changes with care.`,'ust5']];$('.stories').innerHTML=stories.map(([tag,title,body,id])=>`<article><span class="number">${tag}</span><h3>${title}</h3><p>${body}</p>${link(byId(id).newsUrl,byId(id).newsName)}</article>`).join('');$('.why').innerHTML='<strong>Why this matters</strong><p><b>Learning interpretation:</b> Monetary policy connects borrowing costs, currencies and equity valuations, but each market also has its own drivers. Copper demand and oil supply can push commodities in different directions. Compare the same period before drawing a cross-market conclusion.</p>';}
async function loadAlternate(){if(loadingSet||savedSets.alternate)return;loadingSet=true;renderSetControls();try{const r=await fetch('data-alternate.json');if(!r.ok)throw Error('Unavailable');const d=validateSet(await r.json(),savedSets.original);savedSets.alternate=d;loadingSet=false;switchSet('alternate');}catch{loadingSet=false;renderSetControls('The second set could not be loaded. Your original set is safe. Please try Refresh examples again.');}}
document.body.dataset.view='overview';
renderSetControls();
fetch('data.json').then(r=>{if(!r.ok)throw Error('Data file unavailable');return r.json();}).then(d=>{savedSets.original=validateSet(d);switchSet('original');registerTools();}).catch(()=>{$('#cards').innerHTML='<p class="notice">The verified data could not be loaded. Please reload this page. No substitute prices have been generated.</p>';});

let ENRICHMENT={}, YF_OBSERVATIONS={};
fetch('yfinance-observations.json').then(r=>r.ok?r.json():{}).then(d=>{YF_OBSERVATIONS=d;if(detailId)renderDetail();}).catch(()=>{});
fetch('insights.json').then(r=>r.ok?r.json():{}).then(d=>{ENRICHMENT=d;if(detailId)renderDetail();}).catch(()=>{});
function insightMarkup(i){const d=ENRICHMENT[i.id];return `<section class="so-what"><h3>So what?</h3><p>${esc(d?.soWhat||'Consider the direction, comparison period and market-specific risks together before drawing a conclusion.')}</p><p><b>Watch next:</b> ${esc(d?.watch||'Whether the move persists across several sessions.')}</p><small>Learning interpretation · not a forecast. Context relates to the dated snapshot.</small></section>`;}
function leadersMarkup(i){if(i.group!=='Stocks')return '';const m=ENRICHMENT[i.id]?.movers;return `<section class="index-movers"><h3>Top leaders & losers</h3><p class="subtle">${esc(m?.period||'18 Sep 2026 vs 17 Sep 2026 close')} · Ranked by stock percentage change, not index-point contribution.</p>${m?.leaders?.length||m?.losers?.length?`<div class="movers-grid">${[['Leaders',m.leaders||[]],['Losers',m.losers||[]]].map(([title,rows])=>`<div><h4>${title}</h4>${rows.length?rows.map(x=>`<p>${link(x.url,esc(x.name))}<strong class="${x.pct>=0?'positive':'negative'}">${sign(x.pct)}%</strong></p>`).join(''):'<p class="subtle">Verified ranking unavailable for this session.</p>'}</div>`).join('')}</div>`:'<p class="quality-note">A complete, dated constituent ranking could not be verified. No market-wide movers are being substituted for this index.</p>'}<p class="subtle">${esc(m?.note||'Rankings require verified index membership and matching closing prices for every constituent.')} ${m?.auditUrl?link(m.auditUrl,'Source audit'):''}</p></section>`;}

function yfinanceMarkup(i){const rows=YF_OBSERVATIONS.observations?.[i.symbol];if(!rows?.length)return '';const last=rows.at(-1);return `<details class="yf-source"><summary>Yahoo Finance / yfinance · verified daily history</summary><p class="subtle">Retrieved ${hkt(YF_OBSERVATIONS.fetchedAt)} · ${link('https://ranaroussi.github.io/yfinance/','About yfinance')} · ${link('yfinance-observations.json','Saved observations')}</p><p class="subtle">${day(last.date)} daily close: <b>${fmt(last.close,i.digits)} ${esc(i.unit)}</b>. This is a daily bar, which may differ from the card’s timestamped quote. yfinance is an independent Python library; this saved dataset does not enable live refresh.</p><table><thead><tr><th>Session date</th><th>Daily close · ${esc(i.unit)}</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${day(p.date)}</td><td>${fmt(p.close,i.digits)}</td></tr>`).join('')}</tbody></table></details>`;}
